--
-- Table structure for table `ai_cluster_runs`
--

DROP TABLE IF EXISTS `ai_cluster_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_cluster_runs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `status` varchar(255) NOT NULL DEFAULT 'pending',
  `started_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `total_customers` int(10) unsigned NOT NULL DEFAULT 0,
  `total_clusters` int(10) unsigned NOT NULL DEFAULT 0,
  `silhouette_score` decimal(6,4) DEFAULT NULL,
  `selected_k` int(10) unsigned DEFAULT NULL,
  `final_inertia` decimal(12,4) DEFAULT NULL,
  `silhouette_scores` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`silhouette_scores`)),
  `inertia_scores` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`inertia_scores`)),
  `data_stats` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`data_stats`)),
