DROP TABLE IF EXISTS `customers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `customers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `shopify_id` varchar(255) NOT NULL,
  `first_name` varchar(255) DEFAULT NULL,
  `last_name` varchar(255) DEFAULT NULL,
  `gender` varchar(20) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `birthday` date DEFAULT NULL,
  `profile_completed_at` timestamp NULL DEFAULT NULL,
  `birthday_rewarded_at` date DEFAULT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `status` varchar(255) DEFAULT NULL,
  `orders_count` int(10) unsigned NOT NULL DEFAULT 0,
  `total_spent` decimal(12,2) NOT NULL DEFAULT 0.00,
  `currency` varchar(3) DEFAULT NULL,
  `shopify_created_at` timestamp NULL DEFAULT NULL,
  `loyalty_points` int(10) unsigned NOT NULL DEFAULT 0,
  `points_pending` int(10) unsigned NOT NULL DEFAULT 0,
  `ai_import_batch_id` bigint(20) unsigned DEFAULT NULL,
  `tier_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `customers_shopify_id_unique` (`shopify_id`),
  KEY `customers_email_index` (`email`),
  KEY `customers_phone_index` (`phone`),
  KEY `customers_status_index` (`status`),
  KEY `customers_tier_id_foreign` (`tier_id`),
  KEY `customers_ai_import_batch_id_foreign` (`ai_import_batch_id`),
  CONSTRAINT `customers_ai_import_batch_id_foreign` FOREIGN KEY (`ai_import_batch_id`) REFERENCES `ai_import_batches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `customers_tier_id_foreign` FOREIGN KEY (`tier_id`) REFERENCES `tiers` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=264785 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
